import 'jest';
import { ITimeLocale, formatTime } from '../../src';

describe('formatTime()', () => {
    const locale: ITimeLocale = {
        second: 'second',
        seconds: 'seconds',
        minute: 'minute',
        minutes: 'minutes',
        hour: 'hour',
        hours: 'hours'
    };

    test('should return the formatted time string', () => {
        expect(formatTime(12345, locale)).toEqual('3 hours 25 minutes');
    });
    test('should include seconds in the response if hasSeconds is true', () => {
        expect(formatTime(12345, locale, true)).toEqual('3 hours 25 minutes 45 seconds');
    });
});